import sys

def comb_brute(d):
    if not d: return []
    M = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    res = ['']
    for ch in d:
        new = []
        for s in res:
            for c in M[ch]:
                new.append(s + c)
        res = new
    return res

if __name__ == '__main__':
    d = sys.stdin.readline().strip()
    for s in comb_brute(d):
        print(s)

import sys

def comb_opt(d):
    if not d: return []
    M = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    res = []
    def dfs(i, cur):
        if i == len(d):
            res.append(cur)
            return
        for c in M[d[i]]:
            dfs(i + 1, cur + c)
    dfs(0, '')
    return res

if __name__ == '__main__':
    d = sys.stdin.readline().strip()
    for s in comb_opt(d):
        print(s)

import sys

def comb_best(d):
    if not d: return []
    M = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    res = []
    path = []
    def dfs(i):
        if i == len(d):
            res.append(''.join(path))
            return
        for c in M[d[i]]:
            path.append(c)
            dfs(i + 1)
            path.pop()
    dfs(0)
    return res

if __name__ == '__main__':
    d = sys.stdin.readline().strip()
    for s in comb_best(d):
        print(s)
